use sakila;


-- 1. List the number of films per category.
SELECT 
    c.category_id,
    c.name AS category_name, 
    COUNT(fc.film_id) AS number_of_films
FROM film_category fc
JOIN category c ON fc.category_id = c.category_id
GROUP BY c.category_id;
    
    
-- 2. Retrieve the store ID, city, and country for each store.
SELECT 
    s.store_id,
    c.city,
    co.country 
FROM store s
JOIN country co ON c.country_id = co.country_id
JOIN city c ON a.city_id = c.city_id 
JOIN address a ON s.address_id = a.address_id;

-- 3. Calculate the total revenue generated by each store in dollars.
SELECT 
    s.store_id, 
    SUM(p.amount) AS total_revenue 
FROM store s
JOIN payment p ON st.staff_id = p.staff_id
JOIN staff st ON s.store_id = st.store_id
GROUP BY s.store_id;

-- 4. Determine the average running time of films for each category.
SELECT 
    c.category_id,
    c.name AS category_name, 
    ROUND(AVG(f.length), 2) AS avg_running_time 
FROM film f
JOIN film_category fc ON f.film_id = fc.film_id
JOIN category c ON fc.category_id = c.category_id
GROUP BY c.category_id;

-- BONUS
-- 5. Identify the film categories with the longest average running time.
SELECT 
    c.category_id,
    c.name AS category_name, 
    ROUND(AVG(f.length), 2) AS avg_running_time
FROM film f
JOIN film_category fc ON f.film_id = fc.film_id
JOIN category c ON fc.category_id = c.category_id
GROUP BY c.category_id
ORDER BY avg_running_time DESC;

-- 6. Display the top 10 most frequently rented movies in descending order.
SELECT 
    f.film_id,
    f.title, 
    COUNT(r.rental_id) AS rental_count 
FROM film f
JOIN inventory i ON f.film_id = i.film_id
JOIN rental r ON i.inventory_id = r.inventory_id
GROUP BY f.film_id
ORDER BY rental_count DESC
LIMIT 10;

-- 7. Determine if "Academy Dinosaur" can be rented from Store 1.
SELECT 
    f.title,
    CASE
        WHEN COUNT(i.inventory_id) > 0 THEN 'Available'
        ELSE 'NOT available'
    END AS availability_status
FROM film f
LEFT JOIN inventory i ON f.film_id = i.film_id AND i.store_id = 1
WHERE f.title = 'Academy Dinosaur'
GROUP BY f.film_id;

-- 8. Provide a list of all distinct film titles with availability status.
SELECT 
    f.title,
    CASE
        WHEN COUNT(i.inventory_id) > 0 THEN 'Available'
        ELSE 'NOT available'
    END AS availability
FROM film f
LEFT JOIN inventory as i using (film_id)
GROUP BY f.film_id
ORDER BY f.title ASC;